const { execSync } = require('child_process');

function runBuildTask(taskName) {
    return execSync(`npm run build -- --task ${taskName}`).toString();
}

function gitCommit(message, branch) {
    execSync(`git add -A && git commit -m "${message}" && git push origin ${branch}`);
}

module.exports = { runBuildTask, gitCommit };
